<?php
require_once __DIR__.'/../includes/bootstrap.php';admin_required();$pdo=db();$stats=['events'=>(int)$pdo->query('SELECT COUNT(*) FROM events')->fetchColumn(),'published'=>(int)$pdo->query("SELECT COUNT(*) FROM events WHERE status='published'")->fetchColumn(),'students'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn(),'registrations'=>(int)$pdo->query("SELECT COUNT(*) FROM registrations WHERE status='registered'")->fetchColumn()];$events=$pdo->query("SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='registered') registered_count FROM events e ORDER BY e.event_date DESC")->fetchAll();$pageTitle='Admin dashboard';require __DIR__.'/../includes/header.php';?><div class="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-4"><div><h1 class="fw-bold">Admin dashboard</h1><p class="text-secondary">Manage events and student registrations.</p></div><a class="btn btn-primary" href="event-form.php">＋ Create event</a></div><div class="row g-3 mb-4"><?php foreach(['Events'=>'events','Published'=>'published','Students'=>'students','Registrations'=>'registrations'] as $label=>$key):?><div class="col-6 col-xl-3"><div class="stat"><small><?=e($label)?></small><strong><?=$stats[$key]?></strong></div></div><?php endforeach;?></div><div class="panel"><h2 class="h5 fw-bold">All events</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Event</th><th>Date</th><th>Seats</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($events as $ev):?><tr><td><?=e($ev['title'])?></td><td><?=e(date('d M Y H:i',strtotime($ev['event_date'])))?></td><td><?=(int)$ev['registered_count']?>/<?=(int)$ev['capacity']?></td><td><?=e(ucfirst($ev['status']))?></td><td><a class="btn btn-sm btn-outline-primary" href="event-form.php?id=<?=(int)$ev['id']?>">Edit</a> <a class="btn btn-sm btn-outline-secondary" href="registrations.php?event_id=<?=(int)$ev['id']?>">List</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>